"""1.1.4: cyberlimbs and cyberoptics with options and structure points, chipware, therapy and cyberpsychosis,
the adrenal booster, linear frames, facedowns and Reputation, pay, drug bonuses to single skills and saves,
thrown range, lasers and microwavers, and the GM's side of it."""
import asyncio, os
from playwright.async_api import async_playwright
from harness import *

SHOTS=os.path.join(OUT,"chrome");os.makedirs(SHOTS,exist_ok=True)
RIG="window.__mr=window.__mr||Math.random;window.rig=l=>{const q=l.map(([n,v])=>(v-0.5)/n);Math.random=()=>{if(!/at d \\(/.test(new Error().stack))return window.__mr();return q.length?q.shift():0.45}};0"
async def main():
    async with async_playwright() as p:
        b=await p.chromium.launch()
        pl=await page(b,"P","player.html");pl.set_default_timeout(8000)
        await make_runner(pl,"Razor")
        await pl.click(".card:has-text('Razor') >> text=Open sheet");await pl.wait_for_timeout(300)
        await pl.evaluate(RIG);J=lambda s:pl.evaluate(s)
        await J("(()=>{const c=curChar();c.eb=200000;c.cyber=c.cyber.filter(x=>!/smartgun|scope|cyberoptic/i.test(x.name));c.weapons=c.weapons.filter(w=>!w.cyber);saveChar(c,true);render()})()")
        CI=await J("Object.fromEntries(CYBER.map((r,i)=>[r[0],i]))")
        async def buy(n):
            await pl.click(f"[data-act=buy][data-k=c][data-i='{CI[n]}']");await pl.wait_for_timeout(60)
        await pl.click("[data-act=tab][data-t=cyber]");await pl.wait_for_timeout(100)
        await pl.click("[data-act=open-modal][data-m=shop][data-tab=Cyberware]");await pl.wait_for_timeout(200)
        await buy("Hammer hand");ok(not await J("curChar().cyber.some(x=>x.name==='Hammer hand')"),"an option with nowhere to go can't be bought")
        await buy("Cyberarm");await buy("Cyberarm");await buy("Cyberleg");await buy("Cyberoptic (one eye)")
        locs=await J("hostsOf(curChar()).map(h=>h.loc)");ok(locs==["rarm","larm","rleg","reye"],"limbs and eyes take the next free side %s"%locs)
        ra=await J("hostsOf(curChar())[0].id")
        await pl.select_option("select[data-act-change=shop-host]",ra);await pl.wait_for_timeout(100)
        for n in ["Hammer hand","Hydraulic rams","Thickened myomar","Storage space"]:await buy(n)
        ok(await J(f"optsOn(curChar(),curChar().cyber.find(x=>x.id==='{ra}')).length")==4,"four options on the right arm")
        await buy("Reinforced joints");ok(await J(f"(curChar().cyber.find(x=>x.name==='Reinforced joints')||{{}}).on")!=ra,"a fifth goes elsewhere (the left arm), not on the full one")
        await buy("Cyberlimb armor (SP 20)");await buy("Superchrome")
        ok(await J(f"optsOn(curChar(),curChar().cyber.find(x=>x.id==='{ra}')).filter(x=>optSpec(x).cover).length")==1,"one covering per limb")
        await buy("MicroVideo optic");await buy("Dartgun optic");ok(not await J("curChar().cyber.some(x=>x.name==='Dartgun optic')"),"a cyberoptic holds 4 spaces: video (2) leaves no room for a dartgun (3)")
        ok("needs a cyberleg" in (await J("cyBuyProblem({...curChar(),cyber:[]},CYBER[%d])"%CI["Web foot"])).lower(),"feet need a cyberleg")
        await pl.click("[data-act=close-modal]");await pl.wait_for_timeout(150)
        s=await J(f"limbSDP(curChar(),curChar().cyber.find(x=>x.id==='{ra}'))");ok(s["dis"]==35 and s["des"]==45,"rams 30/40 plus myomar +5: 35/45 %s"%s)
        ok("×3" in await J(f"limbAttacks(curChar(),curChar().cyber.find(x=>x.id==='{ra}'))"),"hydraulic rams: triple punch and crush damage")
        ok(await J("spAt(curChar(),'rarm')")>=20,"limb armor protects the arm (SP 20)")
        t=await pl.text_content("main");ok("Cyberlimbs & cyberoptics" in t and "option spaces" in t and "Structure" in t,"the Cyberware tab shows each limb with its options and structure")
        await pl.screenshot(path=os.path.join(SHOTS,"limbs.png"),full_page=True)
        # a hit on the cyberarm
        w0=await J("curChar().wounds");await pl.click("[data-act=tab][data-t=combat]");await pl.wait_for_timeout(100)
        await pl.fill("#dmg-amt","40");await pl.select_option("select[data-act-change=dmg-loc]","rarm");await pl.click("[data-act=dmg-calc]");await pl.wait_for_timeout(100)
        r=await J("ui.dmg.result");ok(r["limb"]==ra and r["wounds"]==0 and "no stun save" in r["text"].lower(),"damage to a cyberarm goes to the limb, not the runner")
        await pl.click("[data-act=dmg-apply]");await pl.wait_for_timeout(100)
        ok(await J(f"curChar().cyber.find(x=>x.id==='{ra}').sdpDmg")==r["sdp"]==40-await J("hitSP(spAt(curChar(),'rarm'),{})") and await J("curChar().wounds")==w0,"applied to its structure points")
        ok(await J(f"limbState(curChar(),curChar().cyber.find(x=>x.id==='{ra}'))")=="working","still working under 35")
        # removing a limb leaves its options looking for a home
        await pl.click("[data-act=tab][data-t=cyber]");await pl.wait_for_timeout(100)
        la=await J("hostsOf(curChar())[1]");i=await J(f"curChar().cyber.findIndex(x=>x.id==='{la['id']}')")
        await pl.click(f"[data-act=edit-item][data-id='{la['id']}']");await pl.wait_for_timeout(80)
        await pl.click(f"[data-act=del-item][data-list=cyber][data-i='{i}']");await pl.click(f"[data-act=del-item][data-list=cyber][data-i='{i}']");await pl.wait_for_timeout(100)
        ok("Options with nowhere to go" in await pl.text_content("main"),"removing a limb leaves its options with nowhere to go")
        # chipware
        await J("(()=>{const c=curChar();c.skills.Handgun={c:6,p:0,b:0};saveChar(c,true);render()})()");await pl.wait_for_timeout(100)
        await pl.click("[data-act=open-modal][data-m=shop][data-tab=Cyberware]");await pl.wait_for_timeout(150)
        await buy("Neural processor");await buy("Chipware socket");await pl.click("[data-act=close-modal]");await pl.wait_for_timeout(100)
        await pl.select_option("select[data-act-change=chip-pick]","Handgun");await pl.click("[data-act=chip-lvl][data-v='2']");await pl.click("[data-act=chip-buy]");await pl.wait_for_timeout(100)
        ch=await J("curChar().chips[0]");ok(ch["skill"]=="Handgun" and ch["lvl"]==2 and ch["kind"]=="APTR" and ch["cost"]==600,"a Handgun +2 reflex chip: 300eb a level")
        await pl.click(f"[data-act=chip-slot][data-id='{ch['id']}']");await pl.wait_for_timeout(100)
        ok(await J("skillLevel(curChar(),'Handgun')")==6,"not chipped in yet: your own Handgun 6")
        for _ in range(4):await pl.click(f"[data-act=chip-day][data-id='{ch['id']}']");await pl.wait_for_timeout(40)
        ok(await J("skillLevel(curChar(),'Handgun')")==2 and await J("skillNatural(curChar(),'Handgun')")==6,"after 4 days of practice the chip sets Handgun to 2, lower than her own")
        ok(await J("ipCost(curChar(),'Handgun')")==60,"improving still costs by her own level")
        await pl.click("[data-act=tab][data-t=skills]");await pl.wait_for_timeout(100);ok(await pl.locator(".chipmark").count()>=1,"the skill list marks a chipped skill")
        await pl.click("[data-act=tab][data-t=cyber]");await pl.wait_for_timeout(100)
        # adrenal booster, therapy
        await pl.click("[data-act=open-modal][data-m=shop][data-tab=Cyberware]");await pl.wait_for_timeout(150);await buy("Adrenal booster");await buy("Linear frame Σ (Sigma)");await pl.click("[data-act=close-modal]");await pl.wait_for_timeout(100)
        k=await J("(()=>{const k=calc(curChar());return [k.lift,k.melee,k.frame&&k.frame.str]})()");ok(k[0]==600 and k[1]>=4 and k[2]==12,"a Sigma frame: lifts 600kg, +4 melee damage %s"%k)
        ref0=await J("calc(curChar()).eff.REF");ad=await J("curChar().cyber.find(x=>x.name==='Adrenal booster').id")
        await J("rig([[6,4]])");await pl.click(f"[data-act=cy-adrenal][data-id='{ad}']");await pl.wait_for_timeout(100)
        ok(await J("calc(curChar()).eff.REF")==ref0+1 and "6 turns" in await J("curChar().fx.find(f=>f.name==='Adrenal booster').until"),"the adrenal booster: +1 REF for 1D6+2 turns")
        await pl.click(f"[data-act=cy-adrenal][data-id='{ad}']");await pl.click(f"[data-act=cy-adrenal][data-id='{ad}']");await pl.click(f"[data-act=cy-adrenal][data-id='{ad}']");await pl.wait_for_timeout(100)
        ok(await J("curChar().adrenalUsed")==3,"three times a day")
        await J("(()=>{const c=curChar();medDays(c,1);saveChar(c,true);render()})()");ok(await J("curChar().adrenalUsed")==0,"a day passing recharges it")
        await J("(()=>{const c=curChar();c.humanityAdj=-200;saveChar(c,true);render()})()");await pl.wait_for_timeout(100)
        ok("Cyberpsychosis" in await pl.text_content("main") and await J("calc(curChar()).eff.EMP")==0,"at EMP 0 the sheet says cyberpsychosis")
        ok("needs every implant" in await pl.text_content("main"),"therapy waits until the implants are off")
        await J("(()=>{const c=curChar();c.cyber.forEach(x=>x.off=true);saveChar(c,true);render()})()");await pl.wait_for_timeout(100)
        ok(await J("calc(curChar()).lift")!=600,"switched-off implants stop working (the frame)")
        h0=await J("calc(curChar()).humanity");await pl.fill("input[data-cyui=weeks]","2");await pl.click("[data-act=cy-therapy]");await pl.wait_for_timeout(100)
        ok(await J("calc(curChar()).humanity")==h0+40,"two weeks of therapy: +40 Humanity (2 EMP a week)")
        await J("(()=>{const c=curChar();c.cyber.forEach(x=>x.off=false);c.humanityAdj=0;saveChar(c,true);render()})()")
        # facedown and rep
        await pl.click("[data-act=tab][data-t=skills]");await pl.wait_for_timeout(100);await pl.click("[data-act=open-modal][data-m=facedown]");await pl.wait_for_timeout(100)
        await pl.fill("#fd-n","Ironmaster");await pl.fill("#fd-c","4");await pl.fill("#fd-r","6");await J("rig([[10,9],[10,2]])");await pl.click("[data-act=fd-roll]");await pl.wait_for_timeout(100)
        e=await J("Dice.log[0]");ok(e["label"].startswith("Facedown") and "Ironmaster loses" in e["detail"],"a facedown: COOL + Rep + 1D10 each; the loser backs down or fights at −3")
        await pl.screenshot(path=os.path.join(SHOTS,"facedown.png"));await pl.click("[data-act=close-modal]")
        await J("rig([[10,2]])");await pl.click("[data-act=rep-known]");await pl.wait_for_timeout(80);ok("know who you are" in await J("Dice.log[0].detail"),"strangers know you on 1D10 at or under your Rep")
        # pay
        await pl.click("[data-act=tab][data-t=gear]");await pl.wait_for_timeout(100);t=await pl.text_content("main")
        job=await J("jobOf(curChar())");ok(job["title"] in t,"Lifestyle shows the job: "+job["title"])
        eb=await J("curChar().eb");await pl.click("[data-act=get-paid]");await pl.wait_for_timeout(80);ok(await J("curChar().eb")==eb+job["pay"],"getting paid adds the month's pay")
        ok(await J("ROLES.Media.income[3]")==5000 and await J("ROLES.Cop.income[3]")==5000,"Media and Cop at level 8 earn the book's 5,000eb")
        # drug bonuses to one skill, saves
        await J("(()=>{const c=curChar();c.gear.push({id:uid(),name:'Stim',qty:1,cost:500,notes:'',drug:drugBook('Stim')});c.skills.Endurance={c:2,p:0,b:0};saveChar(c,true);render()})()")
        gid=await J("curChar().gear.find(g=>g.name==='Stim').id");await pl.click("[data-act=tab][data-t=med]");await pl.wait_for_timeout(100)
        b0=await J("ckParts(curChar(),'Endurance').base");await pl.click(f"[data-act=med-dose][data-gid='{gid}']");await pl.wait_for_timeout(100)
        ok(await J("ckParts(curChar(),'Endurance').base")==b0+3,"Stim: +3 to Endurance checks")
        await J("(()=>{const c=curChar();c.cyber.push(mkCyber(CYBER.find(r=>r[0]==='Toxin binders'),1));saveChar(c,true);render()})()");await pl.wait_for_timeout(100)
        await J("rig([[10,10]])");await pl.click("[data-act=med-save][data-v=poison]");await pl.wait_for_timeout(80)
        ok("+4 Toxin binders" in await J("Dice.log[0].detail"),"a save against poison includes toxin binders' +4")
        # thrown range, laser, microwaver
        ok(await J("atkRange(mkWeapon(WEAPONS.find(r=>r[0]==='Shuriken')),curChar())")==3*await J("calc(curChar()).eff.BODY"),"shuriken reach BODY × 3")
        ok(await J("atkRange(mkWeapon(WEAPONS.find(r=>r[0]==='Grenade (fragmentation)')),curChar())")==10*await J("calc(curChar()).eff.BODY"),"grenades reach 10 × BODY")
        await J("(()=>{const c=curChar();c.weapons.push(mkWeapon(WEAPONS.find(r=>r[0]==='Militech Elect. LaserCannon')));c.weapons.push(mkWeapon(WEAPONS.find(r=>r[0]==='Techtronica 15 Microwaver')));c.skills.Rifle={c:6,p:0,b:0};saveChar(c,true);render()})()")
        lz=await J("curChar().weapons.find(w=>/Laser/.test(w.name)).id");mw=await J("curChar().weapons.find(w=>/Microwaver/.test(w.name)).id")
        await pl.click("[data-act=tab][data-t=combat]");await pl.wait_for_timeout(100);await pl.click("[data-act=atk-open] >> nth=0");await pl.wait_for_timeout(150)
        await pl.click(f"[data-act=atk-pick][data-id='{lz}']");await pl.click("[data-act=atk-power][data-v='5']");await pl.click("[data-act=atk-dv][data-v='10']");await pl.wait_for_timeout(100)
        ok(await J(f"atkDmgExpr(curChar(),atkWeapon(curChar(),'{lz}'),ui.atk)")=="5D6","laser power dialed to 5D6")
        await J("window.__d=d10x;d10x=()=>[9];0");await pl.click("[data-act=atk-roll]");await pl.wait_for_timeout(150)
        ok(await J(f"curChar().weapons.find(w=>w.id==='{lz}').ammo")==5,"a 5D6 shot uses 5 of the powerpack's 10D6")
        await pl.click(f"[data-act=atk-pick][data-id='{mw}']");await pl.click("[data-act=atk-dv][data-v='10']");await pl.click("[data-act=atk-roll]");await pl.wait_for_timeout(150)
        ok(await pl.locator("[data-act=atk-microwave]").count()==1,"a microwaver hit offers the side-effects roll")
        await J("rig([[6,4],[6,1],[10,7]])");await pl.click("[data-act=atk-microwave]");await pl.wait_for_timeout(80)
        ok("right arm" in await J("Dice.log[0].detail") and "7 turns" in await J("Dice.log[0].detail"),"microwaver 4: a cyberlimb locks up (rolled limb and turns)")
        await J("d10x=window.__d;0");await pl.click("[data-act=close-modal]")
        bad=await J("[...document.querySelectorAll('*')].flatMap(e=>[...e.attributes].map(a=>a.name)).filter(n=>/['\"=]/.test(n))");ok(not bad,"no broken attributes %s"%bad[:3])
        print("player errors:",errs)

        # ---------------- GM ----------------
        gm=await page(b,"GM","gm.html");gm.set_default_timeout(8000);await gm.evaluate(RIG)
        await gm.evaluate("()=>{const c=normalizeChar({...clone(SAMPLE),id:'pc1',handle:'Ghost'});c.cyber.push({...mkCyber(CYBER.find(r=>r[0]==='Cyberarm'),5)});c.humanityAdj=-300;st.party.push(normalizeChar(c));persist();render()}")
        ok(await gm.evaluate("pc('pc1').cyber.find(x=>x.name==='Cyberarm').loc")=="rarm","an older sheet's cyberarm gets a side when it loads")
        await gm.click("nav [data-act=tab][data-t=party]");await gm.wait_for_timeout(150)
        ok("Cyberpsycho" in await gm.text_content("main"),"the party list flags cyberpsychosis")
        await gm.click("[data-act=open-pc][data-id=pc1] >> nth=0");await gm.wait_for_timeout(150)
        ok("Cyberlimbs" in await gm.text_content("main") and "Cyberpsychosis" in await gm.text_content("main"),"the runner's page shows the cyberlimb and the cyberpsychosis banner")
        await gm.evaluate("()=>{const c=pc('pc1');c.humanityAdj=0;c.wounds=17;c.med={};persist();render()}");await gm.wait_for_timeout(100)
        ok("Not stabilized" in await gm.text_content(".panel:has(h3:text('Wounds'))"),"the wound panel shows Not stabilized")
        await gm.click("[data-act=close-pc]")
        await gm.click("nav [data-act=tab][data-t=encounter]");await gm.wait_for_timeout(150)
        await gm.evaluate("()=>{pc('pc1').wounds=0;pc('pc1').med={}}")
        await gm.click("[data-act=enc-add-party]");await gm.select_option("#enc-npc","t-corpsec");await gm.fill("#enc-count","1");await gm.click("[data-act=enc-add-npc]");await gm.wait_for_timeout(150)
        cid=await gm.evaluate("st.encounter.list.find(x=>x.kind==='pc').cid")
        await gm.fill(f"#dmg-{cid}","25");await gm.select_option(f"select[data-act-change=cb-loc][data-cid='{cid}']","rarm");await gm.click(f"[data-act=cb-hit][data-cid='{cid}']");await gm.wait_for_timeout(150)
        ok(await gm.evaluate("pc('pc1').cyber.find(x=>x.name==='Cyberarm').sdpDmg")>0 and await gm.evaluate("pc('pc1').wounds")==0,"the GM's Apply hit on a cyberarm damages the limb")
        await gm.click("[data-act=open-modal][data-m=facedown]");await gm.wait_for_timeout(150);await gm.evaluate("rig([[10,9],[10,1]])");await gm.click("[data-act=fdg-roll]");await gm.wait_for_timeout(150)
        ok((await gm.evaluate("Dice.log[0].label")).startswith("Facedown") and "−3 to attack" in await gm.evaluate("st.encounter.list.map(x=>x.note||'').join(' ')"),"a facedown in the tracker notes the loser's −3")
        await gm.screenshot(path=os.path.join(SHOTS,"gm-facedown.png"));await gm.click("[data-act=close-modal]")
        await gm.evaluate("ui.modal='shop-setup';renderModal()");await gm.wait_for_timeout(150)
        ok(await gm.locator("[data-act=shopset-tab][data-v=dr]").count()==1 and await gm.locator("[data-act=shopset-tab][data-v=bs]").count()==1,"the campaign shop covers drugs and the bodyshop")
        await gm.click("[data-act=close-modal]")
        await gm.click("nav [data-act=tab][data-t=reference]");await gm.wait_for_timeout(150)
        t=await gm.text_content("main");ok(all(x in t for x in ["Cyberlimbs","Chipware","Facedowns","Occupations","Linear frames","Microwaver side effects","Therapy"]),"the rules reference has the new tables")
        print("errors:",errs);ok(not errs,"no page errors")
        await b.close()
    finish()
asyncio.run(main())
